/**
 * TypeScript Editor Support for Node-RED
 * Provides Monaco editor configuration and type acquisition
 */

// Ensure RED.editor.types namespace exists
if (!RED.editor.types) {
    RED.editor.types = {};
}

RED.editor.types.typescript = (function() {
    
    // Track loaded type definitions
    const loadedTypes = new Set();
    const typeCache = new Map();
    
    /**
     * Initialize TypeScript support for Monaco editor
     */
    function init() {
        console.log('[TS] Initializing TypeScript support...');
        
        if (!window.monaco) {
            console.warn("[TS] Monaco editor not loaded, TypeScript support unavailable");
            return;
        }
        
        console.log('[TS] Monaco editor found, configuring TypeScript...');
        
        // Configure TypeScript compiler options
        monaco.languages.typescript.typescriptDefaults.setCompilerOptions({
            target: monaco.languages.typescript.ScriptTarget.ES2020,
            module: monaco.languages.typescript.ModuleKind.CommonJS,
            lib: ['es2020'],
            moduleResolution: monaco.languages.typescript.ModuleResolutionKind.NodeJs,
            esModuleInterop: true,
            allowSyntheticDefaultImports: true,
            resolveJsonModule: true,
            strict: false, // Less strict for function nodes
            noImplicitAny: false,
            skipLibCheck: true,
            baseUrl: '.',
            paths: {
                "@userDir/*": ["*"],
                "@lib/*": ["lib/*"],
                "@nodes/*": ["nodes/*"]
            }
        });
        
        console.log('[TS] TypeScript compiler options configured');
        
        // Set diagnostic options
        monaco.languages.typescript.typescriptDefaults.setDiagnosticsOptions({
            noSemanticValidation: false,
            noSyntaxValidation: false,
            diagnosticCodesToIgnore: [
                2307, // Cannot find module (for @userDir imports)
                2304  // Cannot find name (for Node-RED globals)
            ]
        });
        
        console.log('[TS] TypeScript diagnostic options configured');
        
        // Add Node-RED ambient declarations
        addNodeRedTypes();
        
        // Load cached types
        loadCachedTypes();
        
        console.log('[TS] TypeScript support initialization complete');
    }
    
    /**
     * Add Node-RED specific type definitions
     */
    function addNodeRedTypes() {
        console.log('[TS] Adding Node-RED type definitions...');
        
        const nodeRedTypes = `
        declare global {
            // Message object
            interface NodeMessage {
                payload: any;
                topic?: string;
                _msgid?: string;
                [key: string]: any;
            }
            
            // Function signatures
            interface NodeSend {
                (msg: NodeMessage | NodeMessage[] | NodeMessage[][]): void;
            }
            
            interface NodeDone {
                (error?: Error): void;
            }
            
            // Context object
            interface NodeContext {
                get(key: string): any;
                get(key: string, store: string): any;
                set(key: string, value: any): void;
                set(key: string, value: any, store: string): void;
                keys(): string[];
                keys(store: string): string[];
                global: GlobalContext;
                flow: FlowContext;
            }
            
            interface GlobalContext {
                get(key: string): any;
                get(key: string, store: string): any;
                set(key: string, value: any): void;
                set(key: string, value: any, store: string): void;
                keys(): string[];
                keys(store: string): string[];
            }
            
            interface FlowContext {
                get(key: string): any;
                get(key: string, store: string): any;
                set(key: string, value: any): void;
                set(key: string, value: any, store: string): void;
                keys(): string[];
                keys(store: string): string[];
            }
            
            // Environment object
            interface NodeEnvironment {
                get(key: string): string | undefined;
            }
            
            // Node object
            interface Node {
                id: string;
                name: string;
                outputCount: number;
                log(...args: any[]): void;
                warn(...args: any[]): void;
                error(...args: any[]): void;
                debug(...args: any[]): void;
                trace(...args: any[]): void;
                status(status: {fill?: 'red'|'green'|'yellow'|'blue'|'grey', shape?: 'ring'|'dot', text?: string}): void;
                send: NodeSend;
                done: NodeDone;
            }
            
            // RED utility object
            interface REDUtil {
                cloneMessage(msg: NodeMessage): NodeMessage;
                generateId(): string;
                getMessageProperty(msg: NodeMessage, prop: string): any;
                setMessageProperty(msg: NodeMessage, prop: string, value: any, createMissing?: boolean): void;
                getObjectProperty(obj: any, prop: string): any;
                setObjectProperty(obj: any, prop: string, value: any, createMissing?: boolean): void;
                evaluateNodeProperty(value: any, type: string, node: any, msg: NodeMessage): any;
                prepareJSONataExpression(expr: string, node: any): any;
                evaluateJSONataExpression(expr: any, msg: NodeMessage, callback: (err: Error | null, result: any) => void): void;
                normalisePropertyExpression(str: string): string;
            }
            
            interface RED {
                util: REDUtil;
            }
            
            // Global variables available in function nodes
            const msg: NodeMessage;
            const send: NodeSend;
            const done: NodeDone;
            const node: Node;
            const context: NodeContext;
            const flow: FlowContext;
            const global: GlobalContext;
            const env: NodeEnvironment;
            const RED: RED;
            
            // UserDir imports
            function requireUserDir(module: string): any;
            
            // Node.js globals
            const Buffer: typeof globalThis.Buffer;
            const console: Console;
            const process: Pick<NodeJS.Process, 'env' | 'version' | 'versions' | 'platform' | 'arch'>;
            const setTimeout: typeof globalThis.setTimeout;
            const clearTimeout: typeof globalThis.clearTimeout;
            const setInterval: typeof globalThis.setInterval;
            const clearInterval: typeof globalThis.clearInterval;
            const setImmediate: typeof globalThis.setImmediate;
            const clearImmediate: typeof globalThis.clearImmediate;
        }
        
        export {};
        `;
        
        monaco.languages.typescript.typescriptDefaults.addExtraLib(
            nodeRedTypes,
            'file:///node-red-types.d.ts'
        );
        
        loadedTypes.add('node-red-types');
        console.log('[TS] Node-RED type definitions added');
    }
    
    /**
     * Load type definitions for a package
     */
    async function loadPackageTypes(packageName) {
        console.log(`[TS] Loading package types for: ${packageName}`);
        
        if (loadedTypes.has(packageName)) {
            console.log(`[TS] Package types already loaded for: ${packageName}`);
            return;
        }
        
        try {
            // Check cache first
            if (typeCache.has(packageName)) {
                console.log(`[TS] Found cached types for: ${packageName}`);
                const cached = typeCache.get(packageName);
                monaco.languages.typescript.typescriptDefaults.addExtraLib(
                    cached.content,
                    cached.path
                );
                loadedTypes.add(packageName);
                return;
            }
            
            // Try to load from @types package
            const typesPackage = packageName.startsWith('@types/') ? packageName : `@types/${packageName}`;
            console.log(`[TS] Fetching types from: https://unpkg.com/${typesPackage}/index.d.ts`);
            
            const response = await fetch(`https://unpkg.com/${typesPackage}/index.d.ts`);
            
            if (response.ok) {
                const content = await response.text();
                const path = `file:///node_modules/${typesPackage}/index.d.ts`;
                
                monaco.languages.typescript.typescriptDefaults.addExtraLib(content, path);
                
                // Cache the type definition
                typeCache.set(packageName, { content, path });
                loadedTypes.add(packageName);
                
                console.log(`[TS] Successfully loaded types for: ${packageName}`);
                
                // Save to localStorage
                saveCachedTypes();
            } else {
                console.warn(`[TS] Failed to load types for ${packageName}: ${response.status}`);
            }
        } catch (error) {
            console.warn(`[TS] Error loading types for ${packageName}:`, error);
        }
    }
    
    /**
     * Load types from userDir
     */
    async function loadUserDirTypes() {
        console.log('[TS] Loading userDir types...');
        
        try {
            // First, get list of TypeScript files
            console.log('[TS] Fetching userDir file list...');
            const listResponse = await fetch('function/typescript/userdir-list');
            
            if (!listResponse.ok) {
                console.error(`[TS] Failed to fetch userDir file list: ${listResponse.status}`);
                return [];
            }
            
            const { files, userDir } = await listResponse.json();
            console.log(`[TS] Found ${files.length} TypeScript files in userDir:`, userDir);
            console.log('[TS] Files:', files);
            
            // Load each TypeScript file into Monaco
            const loadPromises = files.map(async (file) => {
                try {
                    console.log(`[TS] Loading userDir file: ${file.path}`);
                    const response = await fetch(`function/typescript/userdir/${file.fullPath}`);
                    
                    if (response.ok) {
                        const content = await response.text();
                        console.log(`[TS] Content for ${file.path}:`, content.substring(0, 200) + '...');
                        
                        // Create multiple paths for better module resolution
                        const paths = [
                            `file:///userDir/${file.fullPath}`,
                            `file:///@userDir/${file.fullPath}`,
                            `file:///@userDir/${file.fullPath.replace(/\.(ts|tsx)$/, '')}`
                        ];
                        
                        // Add to Monaco's TypeScript extra libs with multiple paths
                        for (const path of paths) {
                            monaco.languages.typescript.typescriptDefaults.addExtraLib(
                                content,
                                path
                            );
                        }
                        
                        console.log(`[TS] Added userDir type library: ${file.path}`);
                        console.log(`[TS] - Paths: ${paths.join(', ')}`);
                        
                        return { file, content, success: true };
                    } else {
                        console.error(`[TS] Failed to load ${file.path}: ${response.status}`);
                        return { file, success: false, error: response.status };
                    }
                } catch (err) {
                    console.error(`[TS] Error loading ${file.path}:`, err);
                    return { file, success: false, error: err.message };
                }
            });
            
            const results = await Promise.all(loadPromises);
            const successful = results.filter(r => r.success);
            const failed = results.filter(r => !r.success);
            
            console.log(`[TS] Successfully loaded ${successful.length} userDir types`);
            if (failed.length > 0) {
                console.warn(`[TS] Failed to load ${failed.length} userDir types:`, failed);
            }
            
            return files;
        } catch (error) {
            console.error('[TS] Error loading userDir types:', error);
            return [];
        }
    }
    
    /**
     * Save cached types to localStorage
     */
    function saveCachedTypes() {
        try {
            const cacheData = {
                version: 1,
                types: Array.from(typeCache.entries()).map(([name, data]) => ({
                    name,
                    ...data
                }))
            };
            localStorage.setItem('node-red-typescript-cache', JSON.stringify(cacheData));
            console.log('[TS] Cached types saved to localStorage');
        } catch (error) {
            console.warn('[TS] Failed to save type cache:', error);
        }
    }
    
    /**
     * Load cached types from localStorage
     */
    function loadCachedTypes() {
        try {
            const cached = localStorage.getItem('node-red-typescript-cache');
            if (cached) {
                const cacheData = JSON.parse(cached);
                if (cacheData.version === 1) {
                    for (const type of cacheData.types) {
                        typeCache.set(type.name, {
                            content: type.content,
                            path: type.path
                        });
                        monaco.languages.typescript.typescriptDefaults.addExtraLib(
                            type.content,
                            type.path
                        );
                        loadedTypes.add(type.name);
                    }
                    console.log(`[TS] Loaded ${cacheData.types.length} cached types from localStorage`);
                }
            }
        } catch (error) {
            console.warn('[TS] Failed to load cached types:', error);
        }
    }
    
    /**
     * Setup auto-import detection
     */
    function setupAutoImport(editor) {
        console.log('[TS] Setting up auto-import detection...');
        
        let importTimeout;
        
        editor.onDidChangeModelContent(() => {
            clearTimeout(importTimeout);
            importTimeout = setTimeout(() => {
                detectImports(editor);
            }, 2000);
        });
        
        console.log('[TS] Auto-import detection configured');
    }
    
    /**
     * Detect imports in the editor and load types
     */
    function detectImports(editor) {
        const model = editor.getModel();
        if (!model) return;
        
        const content = model.getValue();
        console.log('[TS] Detecting imports in content...');
        
        // Detect import statements
        const importRegex = /import\s+(?:(?:\{[^}]*\}|\*\s+as\s+\w+|\w+)\s+from\s+)?['"]([^'"]+)['"]/g;
        const requireRegex = /require\s*\(\s*['"]([^'"]+)['"]\s*\)/g;
        
        const imports = new Set();
        
        let match;
        while ((match = importRegex.exec(content)) !== null) {
            imports.add(match[1]);
        }
        while ((match = requireRegex.exec(content)) !== null) {
            imports.add(match[1]);
        }
        
        console.log('[TS] Detected imports:', Array.from(imports));
        
        // Load types for detected imports
        for (const imp of imports) {
            if (!imp.startsWith('.') && !imp.startsWith('@userDir/')) {
                console.log(`[TS] Loading package types for import: ${imp}`);
                loadPackageTypes(imp);
            } else if (imp.startsWith('@userDir/')) {
                console.log(`[TS] UserDir import detected: ${imp}`);
                // UserDir types should already be loaded, but trigger a refresh
                loadUserDirTypes();
            }
        }
    }
    
    /**
     * Compile TypeScript code
     */
    async function compile(code, options = {}) {
        console.log('[TS] Compiling TypeScript code...');
        
        try {
            const response = await fetch('function/typescript/compile', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    code,
                    compilerOptions: options
                })
            });
            
            if (!response.ok) {
                throw new Error(`Compilation failed: ${response.statusText}`);
            }
            
            const result = await response.json();
            console.log('[TS] Compilation result:', result);
            return result;
        } catch (error) {
            console.error('[TS] TypeScript compilation error:', error);
            throw error;
        }
    }
    
    // Initialize when Monaco is ready
    if (window.monaco) {
        console.log('[TS] Monaco already loaded, initializing immediately');
        init();
    } else {
        console.log('[TS] Waiting for Monaco to load...');
        // Wait for Monaco to load
        const checkMonaco = setInterval(() => {
            if (window.monaco) {
                clearInterval(checkMonaco);
                console.log('[TS] Monaco loaded, initializing TypeScript support');
                init();
            }
        }, 100);
    }
    
    return {
        init: init,
        loadPackageTypes: loadPackageTypes,
        loadUserDirTypes: loadUserDirTypes,
        setupAutoImport: setupAutoImport,
        detectImports: detectImports,
        compile: compile
    };
})();